import type { MetadataRoute } from "next";

const APP_URL = process.env.APP_URL ?? "https://nxeon.cloud";

export default function robots(): MetadataRoute.Robots {
  return {
    rules: [
      {
        userAgent: "*",
        allow: "/",
        // Note: /riddle/chamber-of-echoes is GATE 2 of the Nxeon Cipher promo — the one
        // disallowed path that isn't infra. Seekers who "read what the crawlers must
        // not" find the hidden chamber here.
        disallow: ["/dashboard", "/admin", "/api", "/login", "/register", "/forgot-password", "/reset-password", "/riddle/chamber-of-echoes"],
      },
    ],
    sitemap: `${APP_URL}/sitemap.xml`,
    host: APP_URL,
  };
}
