72	/** Product + offers for the pricing page. */
73	export function ProductJsonLd({
74	  plans,
75	}: {
76	  plans: Array<{ name: string; priceCents: number }>;
77	}) {
78	  const offers = plans.map((p) => ({
79	    "@type": "Offer",
80	    name: `${p.name} VPS`,
81	    price: (p.priceCents / 100).toFixed(2),
82	    priceCurrency: "USD",
83	    availability: "https://schema.org/InStock",
84	    url: `${APP_URL}/pricing`,
85	  }));
86	  return (
87	    <JsonLd
88	      data={{
89	        "@context": "https://schema.org",
90	        "@type": "Product",
91	        name: "Nxeon Cloud VPS",
92	        description:
93	          "NVMe cloud VPS with full root access, one-click apps, game servers, and an optional dedicated IPv4.",
94	        brand: { "@type": "Brand", name: "Nxeon" },
95	        offers: {
96	          "@type": "AggregateOffer",
97	          priceCurrency: "USD",
98	          lowPrice: plans.length ? (Math.min(...plans.map((p) => p.priceCents)) / 100).toFixed(2) : undefined,
99	          offerCount: plans.length,
100	          offers,
101	        },
102	      }}
103	    />
104	  );
105	}
