153	/** FAQ rich-result markup. Pass Q/A pairs. */
154	export function FaqJsonLd({ items }: { items: Array<{ q: string; a: string }> }) {
155	  return (
156	    <JsonLd
157	      data={{
158	        "@context": "https://schema.org",
159	        "@type": "FAQPage",
160	        mainEntity: items.map((i) => ({
161	          "@type": "Question",
162	          name: i.q,
163	          acceptedAnswer: { "@type": "Answer", text: i.a },
164	        })),
165	      }}
166	    />
167	  );
168	}
