import { db } from "@/lib/db";

const APP_URL = process.env.APP_URL ?? "https://nxeon.cloud";

export const dynamic = "force-dynamic";

/**
 * llms.txt — an emerging (not yet universally adopted) convention that gives
 * LLM/answer-engine crawlers a compact, curated summary of a site instead of
 * making them parse full HTML. Format: llmstxt.org's spec (single H1, an
 * optional blockquote summary, then H2 sections of "- [Title](url): description"
 * links). No major AI vendor has publicly committed to reading it as of this
 * writing — it's a low-cost bet, not a guaranteed lever.
 *
 * A ROUTE HANDLER, not a static public/llms.txt file, for the same reason
 * app/sitemap.ts and app/robots.ts are code: every price and product fact below
 * is read live from the same catalogue the checkout charges from (see
 * lib/marketing/locationLandings.ts, app/(marketing)/pricing/page.tsx for the
 * established pattern) — never a hand-typed number that can drift stale.
 *
 * HONESTY: only real, verifiable facts. No fabricated customer counts,
 * benchmarks, or review scores — see components/marketing/ReviewBadges.tsx's
 * DEMO_BADGES, which are known-placeholder data and are deliberately NOT
 * repeated here as if real.
 */

/** Same normalisation pricing/page.tsx uses: plans that store a per-term price
 *  (email, game) are divided by their term to get a comparable monthly figure. */
function monthlyOf(p: { priceCents: number; termMonths?: number }): number {
  const t = p.termMonths ?? 1;
  return t > 1 ? Math.round(p.priceCents / t) : p.priceCents;
}

function usd(cents: number): string {
  return `$${(cents / 100).toFixed(2)}`;
}

export async function GET() {
  const [vpsPlans, hostingPlans, emailPlans, gamePlans] = await Promise.all([
    db.plan.findMany({ where: { active: true }, select: { priceCents: true } }),
    db.hostingPlan.findMany({ where: { active: true }, select: { priceCents: true } }),
    db.emailPlan.findMany({ where: { active: true }, select: { priceCents: true, termMonths: true } }),
    db.gamePlan.findMany({ where: { active: true }, select: { priceCents: true, termMonths: true } }),
  ]).catch(() => [[], [], [], []] as const);

  const vpsFrom = vpsPlans.length ? Math.min(...vpsPlans.map((p) => p.priceCents)) : null;
  const hostingFrom = hostingPlans.length ? Math.min(...hostingPlans.map((p) => p.priceCents)) : null;
  const emailFrom = emailPlans.length ? Math.min(...emailPlans.map(monthlyOf)) : null;
  const gameFrom = gamePlans.length ? Math.min(...gamePlans.map(monthlyOf)) : null;

  const lines = [
    "# Nxeon",
    "",
    "> Cloud hosting platform: NVMe cloud VPS, shared web hosting, one-click game",
    "> servers, business email and domain registration. Full root access on VPS,",
    "> instant deployment, free migration from your existing host.",
    "",
    "Every price linked below is read live from the same billing catalogue the",
    "checkout charges from — the number shown to a visitor is the number charged",
    "and the number it renews at. Nxeon's production datacenter is in Singapore;",
    "other city/region pages on this site target those markets and say so plainly",
    "rather than implying a local datacenter that doesn't exist.",
    "",
    "## Products",
    "",
    `- [Cloud VPS](${APP_URL}/vps): Full-root KVM virtual servers on NVMe SSD in a ZFS mirror, dedicated IPv4, DDoS protection on by default${vpsFrom != null ? `. From ${usd(vpsFrom)}/mo` : ""}.`,
    `- [Shared web hosting](${APP_URL}/web-hosting): cPanel-class shared hosting, one-click WordPress, free SSL, free migration from your current host${hostingFrom != null ? `. From ${usd(hostingFrom)}/mo` : ""}.`,
    `- [Game server hosting](${APP_URL}/game-servers): One-click Minecraft, Rust, Valheim, ARK, Palworld and 15+ more titles with a real control panel${gameFrom != null ? `. From ${usd(gameFrom)}/mo` : ""}.`,
    `- [Free Minecraft hosting](${APP_URL}/free-minecraft): A permanently free Minecraft server tier (auto-sleeps when idle, wakes on join) — no card required.`,
    `- [Business email](${APP_URL}/business-email): Hosted mailboxes on Nxeon's own mail platform — webmail, IMAP/SMTP, spam & virus filtering, shared calendars${emailFrom != null ? `. From ${usd(emailFrom)}/mo` : ""}.`,
    `- [Domain registration](${APP_URL}/domains): Register a domain across dozens of TLDs with free WHOIS privacy and DNS management; search a name for the exact live price.`,
    `- [All pricing, one page](${APP_URL}/pricing): Every product line above compared side by side from the live catalogue.`,
    "",
    "## Free tools",
    "",
    `- [Free tools directory](${APP_URL}/tools): Free, no-signup browser utilities — DNS lookup, SSL checker, subnet calculator, WHOIS, port checker, hash/UUID generators and more.`,
    `- [Server size calculator](${APP_URL}/tools/server-size-calculator): Estimate the CPU/RAM/disk a workload needs before choosing a plan.`,
    `- [DNS lookup](${APP_URL}/tools/dns-lookup): Query A/AAAA/MX/TXT/NS records for any domain.`,
    "",
    "## Comparisons & migration",
    "",
    `- [Compare Nxeon](${APP_URL}/compare): Direct, honest feature-and-price comparisons against other VPS hosts, including where a competitor is genuinely the better fit.`,
    `- [Migrate to Nxeon](${APP_URL}/migrate): Free automated migration of files, databases and apps from your current host; nothing changes on the old host until cutover.`,
    "",
    "## Company",
    "",
    `- [About Nxeon](${APP_URL}/about): What Nxeon is and the products it operates.`,
    `- [Trust & security](${APP_URL}/security): Virtualization model (full KVM, not oversold containers), DDoS protection and backup approach.`,
    `- [Contact](${APP_URL}/contact): Talk to a person.`,
    "",
  ];

  return new Response(lines.join("\n"), {
    headers: {
      "content-type": "text/plain; charset=utf-8",
      "cache-control": "public, max-age=3600",
    },
  });
}

